rss.channel:
    {{ title }} | {{ section.title }}
    {{ section_url }}

    {{ (section.description or "")|md2rst|rst2html|forceescape }}
    {{ lang }}
{%- if topics %}
    {{ topics[0].last|rfc822 }}
{%- endif %}
{%- for topic in topics %}


      {{ topic.title }}
      {{ section_url }}/{{ topic.path }}
      {{ section_url }}/{{ topic.path }}
      {{ topic.last|rfc822 }}
      {{ topic.user_name }}
      {{ topic.count }} posts, last by {{ topic.user_name }}

{%- endfor %}
